import{_ as t,o as s,c as e,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Catalogue","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/02-catalog.md","filePath":"generated/modules/02-catalog.md","lastUpdated":null}'),r={name:"modules/02-catalog.md"};function n(i,a,o,p,l,c){return s(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="catalogue" tabindex="-1">Catalogue <a class="header-anchor" href="#catalogue" aria-label="Permalink to &quot;Catalogue&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 0-1 · <a href="/VendoraSystem-docs/specs/02-catalog">spécification complète</a></span></p><p>Référentiel produits du tenant répliqué sur chaque appareil : CRUD produits, codes-barres validés et internes, planches d&#39;étiquettes, recherche locale FTS5 &lt; 100 ms, boutons rapides et modificateurs ; lot R8 : référentiel de TVA, arbre de catégories (couleur, icône, déplacement, suppression), import / export CSV, journal des prix. Les modules métier (variantes, poids, balance, péremption) et les surcharges par magasin ne sont pas commencés.</p><div class="kpis"><div><b>14</b><span>faites</span></div><div><b>6</b><span>partielles</span></div><div><b>5</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="produits" tabindex="-1">Produits <a class="header-anchor" href="#produits" aria-label="Permalink to &quot;Produits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Créer et modifier un produit</strong><br><span class="muted">Nom, catégorie, prix d&#39;achat et de vente en centimes, TVA en pour-mille, suivi de stock, actif ; PATCH périmé → 409.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-02, RG-CAT-03, RG-CAT-05</td><td>0.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-lots-front-existants">📷</a></td></tr><tr><td><strong>Archiver plutôt que supprimer</strong><br><span class="muted">Un produit vendu ne se supprime pas : il se désactive et disparaît de la caisse.<br><i>Case « Actif » faite ; pas de suppression d&#39;un produit jamais vendu ni de 409 « archivez » (CA-10).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td>RG-CAT-06</td><td>0.x</td><td></td></tr><tr><td><strong>Images produits</strong><br><span class="muted">Ajouter des images (JPEG / PNG / WebP) avec miniatures distribuées aux appareils.<br><i>Lot R8c : jusqu&#39;à 10 images par produit (PNG / JPEG ≤ 5 Mo), image d&#39;affichage ≤ 512 px et miniature ≤ 128 px dérivées par le serveur (l&#39;original n&#39;est pas gardé), image principale, retrait ; ProductImagesUpdated vers les caisses, miniature principale téléchargée une fois puis lue hors ligne dans la liste de l&#39;écran de vente (Android, iOS) ; vignettes au back-office ; audit. WebP non accepté (décodeur Java absent).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-07</td><td>R8</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r8cd-images-langues">📷</a></td></tr><tr><td><strong>Référentiel des taux de TVA</strong><br><span class="muted">Le tenant gère sa liste de taux ; un produit référence un taux, jamais un texte libre.<br><i>Lot R8b : référentiel par commerce, pré-rempli à la première lecture avec les taux usuels du pays du premier magasin (fuseau, puis devise : Tunisie, France, Maroc, Algérie, Belgique, Suisse, Sénégal) et ceux déjà portés par les produits ; un produit ne prend qu&#39;un taux actif (422 sinon) ; taux par défaut unique ; désactivation refusée tant que des produits l&#39;utilisent ; bascule en masse des produits vers un autre taux (événements vers les caisses, audit). Gestion OWNER / ADMIN, lecture MANAGER. Le produit garde son taux en valeur (format des caisses inchangé).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-04</td><td>R8</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r8b-tva-categories-csv">📷</a></td></tr><tr><td><strong>Journal des changements de prix</strong><br><span class="muted">Chaque changement de prix, de TVA ou de code-barres est journalisé (avant / après, auteur).<br><i>Lot R8 : création tracée avec son prix ; changement de prix de vente ou d&#39;achat = entrée « Changement de prix » à part (avant / après, devise) ; TVA, code-barres et autres champs en « Modification » ; rien si rien ne change. Lien « Historique des modifications » sur la fiche produit.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-08</td><td>R8</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r8a-journal-inscription">📷</a></td></tr></tbody></table><h2 id="categories" tabindex="-1">Catégories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Catégories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Catégories</strong><br><span class="muted">Organiser les produits en catégories et sous-catégories (arbre ≤ 3 niveaux, couleur, icône, ordre).<br><i>Lot R8b : arbre de trois niveaux au plus (sous-catégories comprises), pas de cycle, couleur #RRGGBB et icône, renommage, déplacement et ordre, suppression d&#39;une catégorie vide — sous-catégories, écran de vente, modificateurs, postes de préparation ou kiosque qui la citent → refus explicite ; produits rangés ailleurs ou « Sans catégorie ». CategoryUpdated / CategoryDeleted vers les caisses ; la couleur colore les boutons de catégorie (Android et iOS). Réorganisation par liste et numéro d&#39;ordre (pas de glisser-déposer).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-10, RG-CAT-11, RG-CAT-12</td><td>0.x, R8</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r8b-tva-categories-csv">📷</a></td></tr></tbody></table><h2 id="codes-barres-etiquettes" tabindex="-1">Codes-barres &amp; étiquettes <a class="header-anchor" href="#codes-barres-etiquettes" aria-label="Permalink to &quot;Codes-barres &amp; étiquettes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Validation des codes-barres</strong><br><span class="muted">Clé GS1 vérifiée (EAN-13, EAN-8, UPC-A), codes libres, préfixe interne refusé à la saisie (422).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-41, RG-CAT-44</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-etiquettes-android">📷</a></td></tr><tr><td><strong>Codes-barres internes</strong><br><span class="muted">Générer des EAN-13 internes (préfixe 20) par séquence serveur, sans collision entre caisses.<br><i>Préfixe interne configurable par tenant : colonne prête, pas d&#39;écran.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-42, RG-CAT-43</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-etiquettes-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-etiquettes-ios">📷</a></td></tr><tr><td><strong>Plusieurs codes par produit</strong><br><span class="muted">Rattacher plusieurs codes-barres (ancien et nouveau conditionnement) à un produit ou une variante.<br><i>Un code au plus par produit (UNIQUE tenant + code) ; table multi-codes prévue plus tard.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-CAT-40</td><td></td><td></td></tr><tr><td><strong>Planches d&#39;étiquettes A4</strong><br><span class="muted">Imprimer une planche PDF (gabarits 24 / 40 / 65, case de départ) avec nom, prix et EAN-13 scannable.<br><i>Sélection par catégorie / réception fournisseur et filtre « prix modifié depuis… » non faits ; EAN-8 non imprimable ; planche physique à imprimer et scanner.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-45</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-etiquettes-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-etiquettes-ios">📷</a></td></tr><tr><td><strong>Étiqueteuses dédiées</strong><br><span class="muted">Imprimer sur une étiqueteuse (ZPL / Brother) via l&#39;agent d&#39;impression local.<br><i>Phase ultérieure (spec 11).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-CAT-45</td><td></td><td></td></tr></tbody></table><h2 id="recherche-scan" tabindex="-1">Recherche &amp; scan <a class="header-anchor" href="#recherche-scan" aria-label="Permalink to &quot;Recherche &amp; scan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Catalogue local sur chaque appareil</strong><br><span class="muted">Le catalogue est tiré du serveur dans la base locale (LWW par version) et reste disponible hors ligne.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td></td><td>0.x, 1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-ios">📷</a></td></tr><tr><td><strong>Recherche produit &lt; 100 ms</strong><br><span class="muted">Recherche insensible aux accents par index FTS5 local, sans réseau, sur 50 000 produits.<br><i>Re-mesure in-app Android sur appareil milieu de gamme ; pas de tri par pertinence ni de recherche sur code-barres partiel.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CAT-70</td><td>1.x, 2.21</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-mesure-100ms-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-mesure-100ms-ios">📷</a></td></tr><tr><td><strong>Scan douchette et caméra</strong><br><span class="muted">Résolution exacte d&#39;un code par douchette HID ou caméra, même quand la recherche a le focus.<br><i>Validation douchette BT / USB et caméra &lt; 500 ms sur matériel physique ; scan pendant une boîte de dialogue perdu sur Android (à décider).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-CAT-71</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-scan-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-scan-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-diagnostic-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-diagnostic-ios">📷</a></td></tr><tr><td><strong>Création rapide d&#39;un produit inconnu</strong><br><span class="muted">Créer en caisse (nom, prix, TVA) un produit au code inconnu, utilisable tout de suite même hors ligne.<br><i>Seul le message « code inconnu » existe ; prévu phase 1 par la spec.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-CAT-71</td><td></td><td></td></tr></tbody></table><h2 id="boutons-rapides" tabindex="-1">Boutons rapides <a class="header-anchor" href="#boutons-rapides" aria-label="Permalink to &quot;Boutons rapides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Boutons rapides</strong><br><span class="muted">Grille de boutons par pages (1×1 / 2×1 / 2×2), presets par profil, éditée au back-office et reçue au pull.<br><i>Éditeur web : publication / 409 / orphelin non capturés sur la vraie stack ; grille visible ou masquée pendant une recherche à trancher.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-72, RG-CAT-73</td><td>1.x, 2.28</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-boutons-rapides-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-identite-appareil">📷</a></td></tr></tbody></table><h2 id="modificateurs" tabindex="-1">Modificateurs <a class="header-anchor" href="#modificateurs" aria-label="Permalink to &quot;Modificateurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Groupes de modificateurs</strong><br><span class="muted">Cuisson, suppléments, retraits : min / max, suppléments, désactivation, rattachement par produit ou catégorie, document versionné.<br><i>Ordre des groupes par produit ; sous-ligne dédiée sur le ticket ; détail des options non agrégé dans les rapports.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-84, RG-CAT-85, RG-CAT-86, RG-CAT-87</td><td>2.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-modificateurs">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-modificateurs-suite">📷</a></td></tr></tbody></table><h2 id="modules-metier" tabindex="-1">Modules métier <a class="header-anchor" href="#modules-metier" aria-label="Permalink to &quot;Modules métier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Variantes taille × couleur</strong><br><span class="muted">Déclarer des axes et générer la matrice de variantes, chacune avec code-barres, prix et stock.<br><i>Lot 4.3 : une variante est un produit enfant (parent_product_id, étiquette « M / Rouge ») avec son code-barres, son stock, son prix et son statut ; axes (1 ou 2, ≤ 20 valeurs, ≤ 100 variantes) définis au back-office, matrice générée, combinaisons retirées archivées, parent renommé → variantes renommées. Caisses : le parent seul apparaît dans les listes, le tap ouvre le choix de la variante, le scan d&#39;un code de variante est direct. Pas de stock par variante séparé : le stock est celui du produit enfant.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-20, RG-CAT-21, RG-CAT-22, RG-CAT-23</td><td>4.3</td><td><a href="/VendoraSystem-docs/preuves/2026-11-06-43-profils-magasin">📷</a></td></tr><tr><td><strong>Produits au poids</strong><br><span class="muted">Prix au kg et quantités en millièmes ; saisie du poids au clavier en caisse.<br><i>Lot 4.3 : case « Vendu au poids (prix au kg) » sur la fiche produit ; en caisse, le tap ouvre la saisie du poids en grammes (montant calculé en direct), ligne « 0,350 kg × prix/kg » ; exclusif avec les variantes.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-50, RG-CAT-53</td><td>0.x, 4.3</td><td><a href="/VendoraSystem-docs/preuves/2026-11-06-43-profils-magasin">📷</a></td></tr><tr><td><strong>Codes-barres balance</strong><br><span class="muted">Décoder les EAN-13 balance à prix ou poids embarqué via le PLU du produit.<br><i>Lot 4.3 : code balance (PLU 5 chiffres, unique par commerce) sur la fiche produit ; au scan, après les clés code-barres du lot R5, l&#39;étiquette est résolue par son PLU ; PLU inconnu → « Produit balance non référencé ». Schéma (poids ou prix) porté par le préfixe (21–23 / 24–26).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-51, RG-CAT-52</td><td>R5, 4.3</td><td><a href="/VendoraSystem-docs/preuves/2026-11-06-43-profils-magasin">📷</a></td></tr><tr><td><strong>Suivi de péremption</strong><br><span class="muted">Marquer un produit suivi en péremption avec un délai d&#39;alerte.<br><i>Lot 4.3 : « Suivi de péremption » et délai d&#39;alerte (0–365 jours, 30 par défaut) sur la fiche produit, exige le suivi de stock ; lots, FEFO et alertes : spec 05 (lots-dlc-fefo, alertes-peremption).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-60</td><td>4.3</td><td><a href="/VendoraSystem-docs/preuves/2026-11-06-43-profils-magasin">📷</a></td></tr></tbody></table><h2 id="multi-magasins-canaux" tabindex="-1">Multi-magasins &amp; canaux <a class="header-anchor" href="#multi-magasins-canaux" aria-label="Permalink to &quot;Multi-magasins &amp; canaux&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Prix et disponibilité par magasin</strong><br><span class="muted">Un catalogue commun au tenant avec des surcharges de prix et d&#39;assortiment par magasin.<br><i>Catalogue au niveau tenant fait ; surcharges par magasin en phase 3 (spec 14).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-CAT-30, RG-CAT-31, RG-CAT-32, RG-CAT-33</td><td></td><td></td></tr><tr><td><strong>Import / export CSV</strong><br><span class="muted">Importer le catalogue en deux temps (dry-run puis validation) et l&#39;exporter en round-trip.<br><i>Lot R8b : export (« ; », BOM, filtres catégorie avec sous-catégories et statut) ; import en deux temps — rapport à blanc gardé (créations, mises à jour, inchangés, erreurs par ligne, catégories à créer) puis application de tout le fichier en une transaction, refusée s&#39;il reste une erreur ; correspondance id puis code-barres ; en-têtes français acceptés, séparateur détecté ; aller-retour sans changement ; jamais de stock ; audit IMPORTED / EXPORTED. Les colonnes sku, vendu au poids et code balance viendront avec ces champs (modules variantes et poids).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-80, RG-CAT-81, RG-CAT-82, RG-CAT-83</td><td>R8</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r8b-tva-categories-csv">📷</a></td></tr><tr><td><strong>Éligibilité titre-restaurant</strong><br><span class="muted">Marquer les produits éligibles alimentaires au paiement par titre-restaurant (France).<br><i>Livré au lot 3.13 (02/11/2026) : case sur la fiche produit, colonne de l&#39;import / export CSV, audit, diffusion aux caisses (base locale v53) ; mention « TR » sur les lignes éligibles du panier.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CAT-09</td><td>3.13</td><td><a href="/VendoraSystem-docs/preuves/2026-11-02-313-titres-restaurant-web">📷</a></td></tr><tr><td><strong>Publication sur les canaux en ligne</strong><br><span class="muted">Publier un produit sur le menu QR, la commande en ligne et le click &amp; collect.<br><i>Phase 4 (spec 16).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-CAT-09bis</td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Plusieurs codes-barres par produit et écran du préfixe interne.</li><li>Création rapide d&#39;un produit inconnu en caisse.</li><li>Surcharges de prix / disponibilité par magasin (phase 3).</li><li>Étiquettes : sélection par catégorie / réception, filtre de prix, EAN-8, étiqueteuses dédiées.</li><li>Re-mesurer la recherche in-app sur un appareil Android milieu de gamme.</li><li>Variantes : choix manuel d&#39;un stock par variante dans les inventaires et transferts (le stock est celui du produit enfant, déjà compté) ; préfixe et schéma balance réglables par magasin ; colonnes CSV poids / PLU / péremption.</li></ul>',22)])])}const g=t(r,[["render",n]]);export{b as __pageData,g as default};
